<?php $editing=(bool)$product;$old=App\Core\Session::get('_old',[]);$value=static fn($key,$default='')=>$old[$key]??($product[$key]??$default);$optionRows=$old['options']??($product?array_map(static fn($o)=>['name'=>$o['name'],'values'=>implode(', ',array_column($o['values'],'value'))],$product['options']):[['name'=>'','values'=>'']]); ?>
<section class="page-head"><div><a class="back-link" href="/products">← Products</a><h1><?= $editing?'Edit product':'Add product' ?></h1><p class="muted">Build a clean product listing without one enormous form.</p></div></section><form method="post" action="<?= $editing?'/products/'.e($product['id']):'/products' ?>" enctype="multipart/form-data" class="editor-layout product-editor"><?= csrf_field() ?><div class="editor-sections">
<section class="panel form-section"><div class="section-heading"><span>01</span><div><h2>Basic information</h2><p>The details customers will use to understand the product.</p></div></div><div class="form-grid compact-grid"><label class="full">Product name<input name="name" value="<?= e($value('name')) ?>" maxlength="160" required data-slug-source></label><label>Store address<input name="slug" value="<?= e($value('slug')) ?>" maxlength="180" placeholder="generated-from-name" data-slug-target></label><label>SKU <span class="optional">Optional</span><input name="sku" value="<?= e($value('sku')) ?>" maxlength="100"></label><label class="full">Description <span class="optional">Optional</span><textarea name="description" rows="5" maxlength="10000"><?= e($value('description')) ?></textarea></label></div></section>
<section class="panel form-section"><div class="section-heading"><span>02</span><div><h2>Pricing and organization</h2><p>Prices are stored precisely as decimal values.</p></div></div><div class="form-grid compact-grid"><label>Price<input name="price" value="<?= e($value('price','0.00')) ?>" inputmode="decimal" required></label><label>Compare-at price <span class="optional">Optional</span><input name="compare_price" value="<?= e($value('compare_price')) ?>" inputmode="decimal"></label><label class="full">Find category<input type="search" placeholder="Filter categories" data-category-search aria-label="Filter category choices"><select name="category_id" data-category-select><option value="0">Uncategorized</option><?php foreach($categories as$c):?><option value="<?= e($c['id']) ?>" <?= $value('category_id')==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></label><label>Availability<select name="availability"><option value="AVAILABLE" <?= $value('availability','AVAILABLE')==='AVAILABLE'?'selected':'' ?>>Available</option><option value="UNAVAILABLE" <?= $value('availability')==='UNAVAILABLE'?'selected':'' ?>>Unavailable</option></select></label><label>Publishing status<select name="status"><option value="DRAFT" <?= $value('status','DRAFT')==='DRAFT'?'selected':'' ?>>Draft</option><option value="ACTIVE" <?= $value('status')==='ACTIVE'?'selected':'' ?>>Active</option><option value="ARCHIVED" <?= $value('status')==='ARCHIVED'?'selected':'' ?>>Archived</option></select></label><label class="check-row full"><input type="checkbox" name="is_featured" value="1" <?= $value('is_featured')?'checked':'' ?>><span>Feature this product on the storefront</span></label></div></section>
<section class="panel form-section"><div class="section-heading"><span>03</span><div><h2>Images</h2><p>JPEG, PNG, or WebP. 300–6000 px and up to 5 MB each.</p></div></div><?php if($editing&&$product['images']):?><div class="image-manager"><?php foreach($product['images']as$image):?><figure><img src="<?= e($image['thumbnail_path']?:$image['path']) ?>" alt="Product image"><figcaption><button form="delete-image-<?= e($image['id']) ?>" class="button compact danger-ghost" type="submit">Remove</button></figcaption></figure><?php endforeach ?></div><?php endif ?><label class="drop-zone"><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple data-image-input><span><strong>Choose product images</strong><small>Multiple images supported · maximum 8 total</small></span></label><div class="image-previews" data-image-previews></div></section>
<section class="panel form-section"><div class="section-heading"><span>04</span><div><h2>Variants</h2><p>Create options such as Color, Size, Storage, or Flavor.</p></div></div><div class="option-builder" data-option-builder><?php foreach($optionRows as$i=>$option):?><div class="option-row"><label>Option name<input name="options[<?= e($i) ?>][name]" value="<?= e($option['name']??'') ?>" placeholder="Color"></label><label>Values<input name="options[<?= e($i) ?>][values]" value="<?= e($option['values']??'') ?>" placeholder="Black, White, Blue"><small>Separate values with commas.</small></label><button class="icon-button remove-option" type="button" aria-label="Remove option">×</button></div><?php endforeach ?></div><button class="button secondary" type="button" data-add-option>Add another option</button><?php if($editing&&$product['variants']):?><div class="variant-table"><div class="variant-note">Existing combinations retain their data when labels stay unchanged.</div><?php foreach($product['variants']as$variant):?><div class="variant-row"><strong><?= e($variant['label']) ?></strong><input type="hidden" name="variants[<?= e($variant['id']) ?>][present]" value="1"><label>SKU<input name="variants[<?= e($variant['id']) ?>][sku]" value="<?= e($variant['sku']) ?>"></label><label>Price adjustment<input name="variants[<?= e($variant['id']) ?>][price_adjustment]" value="<?= e($variant['price_adjustment']) ?>" inputmode="decimal"></label><label>Stock <span class="optional">Optional</span><input name="variants[<?= e($variant['id']) ?>][stock_quantity]" value="<?= e($variant['stock_quantity']) ?>" inputmode="numeric"></label><label class="check-row"><input type="checkbox" name="variants[<?= e($variant['id']) ?>][is_available]" value="1" <?= $variant['is_available']?'checked':'' ?>><span>Available</span></label></div><?php endforeach ?></div><?php endif ?></section></div>
<aside class="editor-actions panel"><strong><?= $editing?'Save product':'Create product' ?></strong><p>Changes are validated server-side before they are saved.</p><button class="button primary" type="submit"><?= $editing?'Save changes':'Create product' ?></button><a class="button secondary" href="/products">Cancel</a></aside></form>
<?php if($editing&&$product['images']):foreach($product['images']as$image):?><form id="delete-image-<?= e($image['id']) ?>" method="post" action="/products/<?= e($product['id']) ?>/images/<?= e($image['id']) ?>/delete" data-confirm="Remove image?" data-confirm-message="The image file and its thumbnail will be permanently deleted."><?= csrf_field() ?></form><?php endforeach;endif ?>
